-- MedBard topic seed — organ-system structure per exam and mode.
-- Names only, no clinical content. Editable by hand; idempotent guard:
-- it only inserts when the topics table is still empty.
-- Systems named after the case specialties are case-eligible in clinical
-- mode; basic-science systems are preclinical-only and never case-eligible.
-- Run once (e.g. via the database query tools). Safe to re-run.
DO $$
BEGIN
IF (SELECT count(*) FROM public.topics) > 0 THEN
  RAISE NOTICE 'topics already seeded, skipping';
ELSE
-- systems first, then topics, then subtopics (parent lookups rely on order)
END IF;
END $$;
